"""stage4_data.py (Ch 10-14 終極無矛盾版)"""

STAGE_4 = {'title': '第四階：黎曼和、微積分基本定理與對數超越函數發明（第 10–14 堂）', 'theme': '從無窮微元累積到算子對偶，微積分基本定理合流，填補冪函數反導黑洞，自然常數 e 與對數微積分基石確立', 'lessons': [{'id': 10, 'title': '黎曼和與連續曲邊分割求和（定積分算子建立）', 'book_blueprint': '從阿基米德窮竭法躍遷為現代黎曼和極限；四部曲：分割（Partition）、取樣（Sampling）、求和（Summation）、取極限（Limit）；建立定積分符號 $\\int_a^b f(x)\\,\\mathrm{d}x$ 的幾何與算子定義。', 'dojo_core': '黑板直擊：在黑板上以 $f(x)=x^2$ 在 $[0, 1]$ 區間為實彈樣板，利用立方和公式 $\\sum k^2 = \\frac{n(n+1)(2n+1)}{6}$ 手算無窮和極限，讓學生親歷不用反導數而直接算面積的震撼。', 'formulas': [{'id': 'Eq 10.1', 'name': '區間均勻分割步長定義式', 'latex': '\\Delta x = \\frac{b - a}{n}, \\quad x_k = a + k\\Delta x \\quad (k = 0, 1, \\dots, n)'}, {'id': 'Eq 10.2', 'name': '黎曼和矩形面積疊加定義式', 'latex': 'S_n = \\sum_{k=1}^n f(x_k^*) \\Delta x \\quad (x_k^* \\in [x_{k-1}, x_k])'}, {'id': 'Eq 10.3', 'name': '定積分算子極限定義式', 'latex': '\\int_a^b f(x)\\,\\mathrm{d}x = \\lim_{n \\to \\infty} \\sum_{k=1}^n f(x_k^*) \\Delta x = \\lim_{\\|P\\| \\to 0} \\sum_{k=1}^n f(\\xi_k) \\Delta x_k'}, {'id': 'Eq 10.4', 'name': '拋物線阿基米德自然數平方和展開式', 'latex': '\\sum_{k=1}^n k^2 = \\frac{n(n+1)(2n+1)}{6} = \\frac{1}{3}n^3 + \\frac{1}{2}n^2 + \\frac{1}{6}n'}, {'id': 'Eq 10.5', 'name': '單項式平方定積分極限手算式', 'latex': '\\int_0^1 x^2\\,\\mathrm{d}x = \\lim_{n \\to \\infty} \\sum_{k=1}^n \\left(\\frac{k}{n}\\right)^2 \\frac{1}{n} = \\lim_{n \\to \\infty} \\frac{n(n+1)(2n+1)}{6n^3} = \\frac{1}{3}'}, {'id': 'Eq 10.6', 'name': '定積分線性與區間可加公理式', 'latex': '\\int_a^b \\big(\\alpha f + \\beta g\\big)\\,\\mathrm{d}x = \\alpha \\int_a^b f\\,\\mathrm{d}x + \\beta \\int_a^b g\\,\\mathrm{d}x, \\quad \\int_a^b f = \\int_a^c f + \\int_c^b f'}, {'id': 'Eq 10.7', 'name': '可積性達布上下和收斂充要條件', 'latex': '\\lim_{\\|P\\| \\to 0} \\big(U(P, f) - L(P, f)\\big) = 0 \\iff f \\in \\mathcal{R}[a, b]'}], 'problems': {'worked_examples': [{'id': 'Ex 10.1', 'desc': '以區間 $[0, b]$ 上的線性函數 $f(x) = x$ 為例，取右端點分割 $x_k = \\frac{kb}{n}$，寫出黎曼和 $\\sum_{k=1}^n \\frac{kb}{n}\\frac{b}{n}$，利用等差數列求和公式求極限，證明三角形面積公式 $\\frac{1}{2}b^2$。'}, {'id': 'Ex 10.2', 'desc': '在黑板上完整手算拋物線 $f(x) = x^2$ 在 $[0, 1]$ 的黎曼和，取左端點分割與右端點分割，證明二者的極限均精確收斂於 $\\frac{1}{3}$，驗證阿基米德拋物線求積。'}, {'id': 'Ex 10.3', 'desc': '將離散數列極限 $\\lim_{n\\to\\infty} \\sum_{k=1}^n \\frac{n}{n^2 + k^2}$ 識別為某個函數在 $[0, 1]$ 上的定積分黎曼和，構造積分表達式並求出極限值 $\\pi/4$。'}], 'margin_inquiries': [{'id': 'Q1 10.1', 'desc': '【深水思辨】積分符號 $\\int$ 原本是拉長的大寫字母 $S$（拉丁文 Summa，求和），而 $\\mathrm{d}x$ 則是無窮小寬度 $\\Delta x$。為什麼定積分的本質是『乘積的無窮累積』而不是單純的面積？'}, {'id': 'Q1 10.2', 'desc': '【體制內盲點】很多高中生把定積分直接等同於『找反導數代入上下限』。如果在牛頓之前沒有反導數，人類是如何算積分的？為什麼不懂黎曼和就永遠無法建立物理建模？'}, {'id': 'Q1 10.3', 'desc': '【採樣獨立性】在黎曼和中，取樣點 $\\xi_k$ 取在每個子區間的左端點、右端點、中點還是隨機點，最終極限為什麼完全一樣？什麼樣的病態函數會導致取樣不同而極限崩潰？（狄利克雷函數的不可積性）。'}], 'foundational_drills': [{'id': 'P1 10.1', 'desc': '閉卷寫出黎曼積分的四部曲步驟與定義極限式，標明分割細度 $\\|P\\| \\to 0$ 的含義。'}, {'id': 'P1 10.2', 'desc': '利用立方和公式 $\\sum k^3 = \\frac{n^2(n+1)^2}{4}$，用黎曼和極限手算 $\\int_0^1 x^3\\,\\mathrm{d}x = \\frac{1}{4}$。'}, {'id': 'P1 10.3', 'desc': '將極限 $\\lim_{n \\to \\infty} \\frac{1}{n} \\sum_{k=1}^n \\sqrt{\\frac{k}{n}}$ 轉化為定積分形式並求其極限值。'}, {'id': 'P1 10.4', 'desc': '利用定積分保號性與不等式性質，證明：若在 $[a, b]$ 上 $f(x) \\ge m > 0$，則 $\\int_a^b f(x)\\,\\mathrm{d}x \\ge m(b-a)$。'}], 'interdisciplinary_applications': [{'id': 'P5 10.1', 'desc': '【長度質量累積】一根長度為 $L$ 的金屬棒，線密度隨位置非均勻分佈 $\\lambda(x) = \\lambda_0 (1 + x/L)$，利用黎曼和微元分割求總質量 $M = \\int_0^L \\lambda(x)\\,\\mathrm{d}x$。'}, {'id': 'P5 10.2', 'desc': '【電流通量累積】非恆定電流 $I(t) = I_0 \\left(\\frac{t}{T}\\right)^2$ 流過截面，將時間等分成微元 $\\Delta t$，利用黎曼和累積求總電荷量 $Q$。'}, {'id': 'P5 10.3', 'desc': '【水壩靜水壓力】梯形水壩迎水面受水壓，深度 $y$ 處壓強 $P(y) = \\rho g y$，將水壩表面劃分成水平窄條微元，用黎曼和求總側壓力。'}, {'id': 'P5 10.4', 'desc': '【熱力學非等溫熱容量】固體在極低溫下晶格熱容遵循德拜 $T^3$ 定律 $C(T) = k T^3$，求溫度自 $T_1$ 升到 $T_2$ 吸收的總熱量。'}], 'deepwater_challenges': [{'id': 'P9 10.1', 'desc': '【勒貝格積分雛形】分析黎曼積分對橫軸區間分割的侷限，如果對值域縱軸進行分割（將具有相同函數值的點集歸類），思考勒貝格測度求和如何拯救病態不可積函數。'}, {'id': 'P9 10.2', 'desc': '【斯蒂爾吉斯積分雛形】設積分微元不是平權的 $\\mathrm{d}x$ 而是某累積分佈函數的躍遷 $\\mathrm{d}\\alpha(x)$，分析離散點質量與連續線密度如何在黎曼-斯蒂爾吉斯積分中統一起來。'}], 'dojo_defense_tasks': [{'id': 'D1 10.1', 'desc': '學員甲在黑板算 $\\lim_{n\\to\\infty} \\sum_{k=1}^n \\frac{1}{n+k}$，試圖用等差數列通項相加。導師喝令停筆：『把分母提出 $n$ 來！寫成 $\\frac{1}{n} \\frac{1}{1 + k/n}$，大聲告訴全班這是在積哪一個函數？上下限是多少？』'}, {'id': 'D1 10.2', 'desc': '學員乙被要求在黑板解釋為什麼黎曼和定義必須要求『對任意取樣點 $\\xi_k$ 極限都存在且相等』。導師質詢：『如果一個函數只在有理數點等於 1，在無理數點等於 0，上和與下和分別是多少？為什麼它不可積？』'}, {'id': 'D1 10.3', 'desc': '學員丙上黑板展示阿基米德窮竭法求拋物線面積的幾何三角形級數 $\\frac{1}{3} = \\frac{1}{4} + \\frac{1}{16} + \\cdots$，導師詰問幾何級數求和與代數黎曼和極限的深層同構。'}], 'unseen_sandbox_scenarios': [{'id': 'U1 10.1', 'desc': '星系盤面恆星數密度隨半徑指數衰減 $\\sigma(r) = \\sigma_0 e^{-r/R}$，現場將圓盤劃分成同心環狀微元，建立總恆星數量的黎曼和與定積分。'}, {'id': 'U1 10.2', 'desc': '給定某種光學探測器像素陣列感光強度，將離散像素響應矩陣在極限下抽象為連續照度分佈的二維黎曼曲面積分。'}, {'id': 'U1 10.3', 'desc': '連續隨機變數在離散直方圖採樣中的頻率逼近，構造直方圖面積和向機率密度積分的過渡條件。'}], 'system_trivialization_arsenal': [{'id': 'K1 10.1', 'desc': '高中聯考數列極限難題：求 $\\lim_{n\\to\\infty} \\left[\\frac{1}{n^2} + \\frac{2}{n^2} + \\cdots + \\frac{n}{n^2}\\right]$ 與 $\\lim_{n\\to\\infty} \\sum_{k=1}^n \\frac{k^2}{n^3}$。傳統高中生用求和公式算到頭暈，轉譯為定積分 $\\int_0^1 x\\,\\mathrm{d}x = 1/2$ 與 $\\int_0^1 x^2\\,\\mathrm{d}x = 1/3$，5 秒出答案。'}, {'id': 'K1 10.2', 'desc': '高二物理競賽題：非均勻電場中沿曲線移動電荷的電場力功，將曲線分割為微元折線，用黎曼和定義一眼看破保守場路徑無關性。'}, {'id': 'K1 10.3', 'desc': '競賽代數題：求 $\\lim_{n\\to\\infty} \\sqrt[n]{\\frac{n!}{n^n}}$。兩邊取對數化為黎曼和 $\\int_0^1 \\ln x\\,\\mathrm{d}x$，直接得到極限為 $1/e$（斯特林公式雛形）。'}]}}, {'id': 11, 'title': '微積分基本定理（FTC）：對偶統一（變化率與積聚的合流）', 'book_blueprint': '迎來人類智力史上的最高峰之一：微分與積分互為逆運算；證明第一基本定理（變上限積分的微商必為被積函數）與第二基本定理（牛頓-萊布尼茲公式）；徹底終結窮竭法手算和的噩夢。', 'dojo_core': "黑板直擊：在黑板上以面積函數 $A(x) = \\int_a^x f(t)\\,\\mathrm{d}t$ 的增量 $\\Delta A \\approx f(x)\\Delta x$ 為核心，實彈演示除以 $\\Delta x$ 後取極限 $A'(x)=f(x)$ 的神級幾何代數轉譯，徹底融通兩大算子。", 'formulas': [{'id': 'Eq 11.1', 'name': '變上限積分累積函數定義式', 'latex': 'F(x) = \\int_a^x f(t)\\,\\mathrm{d}t \\quad (x \\in [a, b])'}, {'id': 'Eq 11.2', 'name': '變上限函數微元面積增量式', 'latex': '\\Delta F = F(x + \\Delta x) - F(x) = \\int_x^{x+\\Delta x} f(t)\\,\\mathrm{d}t = f(c) \\Delta x \\quad (c \\in [x, x+\\Delta x])'}, {'id': 'Eq 11.3', 'name': '微積分第一基本定理（FTC-1）', 'latex': '\\frac{\\mathrm{d}}{\\mathrm{d}x} \\left( \\int_a^x f(t)\\,\\mathrm{d}t \\right) = f(x) \\quad (f \\text{ 在 } x \\text{ 處連續})'}, {'id': 'Eq 11.4', 'name': '牛頓-萊布尼茲第二基本定理（FTC-2）', 'latex': "\\int_a^b f(x)\\,\\mathrm{d}x = F(b) - F(a) = \\big[ F(x) \\big]_a^b \\quad (F'(x) = f(x))"}, {'id': 'Eq 11.5', 'name': '廣義變限積分連鎖求導式', 'latex': "\\frac{\\mathrm{d}}{\\mathrm{d}x} \\left( \\int_{u(x)}^{v(x)} f(t)\\,\\mathrm{d}t \\right) = f\\big(v(x)\\big) v'(x) - f\\big(u(x)\\big) u'(x)"}, {'id': 'Eq 11.6', 'name': '位移速度加速度三位一體合流式', 'latex': 'x(t) - x(t_0) = \\int_{t_0}^t v(\\tau)\\,\\mathrm{d}\\tau, \\quad v(t) - v(t_0) = \\int_{t_0}^t a(\\tau)\\,\\mathrm{d}\\tau'}, {'id': 'Eq 11.7', 'name': '不連續點 FTC 局部失效檢驗式', 'latex': "f(x) = \\operatorname{sgn}(x) \\implies F(x) = |x| \\implies F'(0) \\text{ 不存在} \\neq f(0) = 0"}], 'problems': {'worked_examples': [{'id': 'Ex 11.1', 'desc': '利用積分中值定理 $\\int_x^{x+\\Delta x} f(t)\\,\\mathrm{d}t = f(c)\\Delta x$，在黑板上無跳步寫出差商 $\\frac{F(x+\\Delta x)-F(x)}{\\Delta x} = f(c)$，證明當 $\\Delta x\\to 0$ 時 $c\\to x$ 且 $f(c)\\to f(x)$，完成 FTC-1 的公理推導。'}, {'id': 'Ex 11.2', 'desc': '求變限積分函數的導數：$G(x) = \\int_0^{x^2} \\sqrt{1 + t^3}\\,\\mathrm{d}t$。利用連鎖律明確寫出外層函數對上限求導與內層上限 $x^2$ 對 $x$ 求導的乘積。'}, {'id': 'Ex 11.3', 'desc': '已知某質點加速度隨時間按正弦規律變化 $a(t) = A\\cos(\\omega t)$，初始速度為 $v(0) = 0$，初始位置為 $x(0) = x_0$。連續兩次應用 FTC-2，求速度函數 $v(t)$ 與位置函數 $x(t)$。'}], 'margin_inquiries': [{'id': 'Q1 11.1', 'desc': '【深水思辨】為什麼牛頓和萊布尼茲被公認為微積分的發明者，而早於他們的阿基米德、費馬、笛卡兒不是？關鍵就在於 FTC！將『求切線（微分）』與『求面積（求和）』這兩個幾千年來毫不相干的幾何問題聯姻為互逆運算，這是人類認知的巨大飛躍。'}, {'id': 'Q1 11.2', 'desc': '【體制內盲點】中學物理老師教 $v-t$ 圖『切線是加速度、面積是位移』時，往往當成兩個割裂的記憶結論。用 FTC 一句話說透：加速度是速度的導數，位移是速度的變上限積分，二者天生對偶！'}, {'id': 'Q1 11.3', 'desc': '【啞鈴變量陷阱】在變上限積分 $\\int_a^x f(t)\\,\\mathrm{d}t$ 中，為什麼被積變量必須寫成 $t$ 而絕不能寫成 $x$？積分號內的 $t$ 稱為『虛變量（Dummy Variable）』，上限的 $x$ 是自變量，二者混淆會引發何種災難？'}], 'foundational_drills': [{'id': 'P1 11.1', 'desc': '閉卷默寫 FTC-1 與 FTC-2 的定理條件與結論公式，標明被積函數的連續性要求。'}, {'id': 'P1 11.2', 'desc': '無跳步計算求導：$f(x) = \\frac{\\mathrm{d}}{\\mathrm{d}x} \\int_1^{\\sin x} (1 - t^2)\\,\\mathrm{d}t$。'}, {'id': 'P1 11.3', 'desc': '求極限：$\\lim_{x \\to 0} \\frac{\\int_0^x \\cos(t^2)\\,\\mathrm{d}t}{x}$。'}, {'id': 'P1 11.4', 'desc': '已知 $F(x) = \\int_0^x (t-1)(t-2)\\,\\mathrm{d}t$，求 $F(x)$ 的極值點與單調區間。'}], 'interdisciplinary_applications': [{'id': 'P5 11.1', 'desc': '【電磁學感應電動勢】穿過閉合迴路的磁通量 $\\Phi(t) = \\int_0^t \\mathcal{E}(\\tau)\\,\\mathrm{d}\\tau$，利用 FTC 求瞬時感應電動勢，驗證法拉第定律與楞次定律。'}, {'id': 'P5 11.2', 'desc': '【熱力學內能狀態量】比熱容 $C_v(T)$ 隨溫度變化，系統吸熱 $\\Delta U = \\int_{T_1}^{T_2} C_v(T)\\,\\mathrm{d}T$，利用 FTC-2 證明只要 $C_v(T)$ 連續，內能即為只取決於始末狀態的狀態函數。'}, {'id': 'P5 11.3', 'desc': '【化學反應累積生成量】反應速率隨時間指數衰減 $r(t) = r_0 e^{-kt}$，利用 FTC 求從 $t=0$ 到任意時刻生成物總質量的封閉表達式。'}, {'id': 'P5 11.4', 'desc': "【信號處理卷積與階躍】階躍響應是衝激響應的變上限積分 $s(t) = \\int_{-\\infty}^t h(\\tau)\\,\\mathrm{d}\\tau$，利用 FTC-1 證明衝激響應是階躍響應的導數 $h(t) = s'(t)$。"}], 'deepwater_challenges': [{'id': 'P9 11.1', 'desc': '【含參變量積分求導萊布尼茲法則】設 $I(x) = \\int_a^b f(x, t)\\,\\mathrm{d}t$（積分限固定，但被積函數含參數 $x$）。證明在偏微商連續條件下 $\\frac{\\mathrm{d}I}{\\mathrm{d}x} = \\int_a^b \\frac{\\partial f(x, t)}{\\partial x}\\,\\mathrm{d}t$。'}, {'id': 'P9 11.2', 'desc': '【柯西-施瓦茨不等式的積分形式】利用 FTC 與非負二次多項式判別式，證明 $\\left( \\int_a^b f(x)g(x)\\,\\mathrm{d}x \\right)^2 \\le \\left( \\int_a^b f^2(x)\\,\\mathrm{d}x \\right) \\left( \\int_a^b g^2(x)\\,\\mathrm{d}x \\right)$。'}], 'dojo_defense_tasks': [{'id': 'D1 11.1', 'desc': '學員甲在黑板求 $\\frac{\\mathrm{d}}{\\mathrm{d}x}\\int_0^x x t\\,\\mathrm{d}t$，直接將 $t$ 換成 $x$ 寫出 $x^2$。導師當面大喝一聲：『停！被積函數裡面的 $x$ 不是虛變量！它對外層微商來說是變量，你必須先把它提到積分號外面，再用乘積求導法則！重寫！』'}, {'id': 'D1 11.2', 'desc': '學員乙被指定在黑板推導上下限均含 $x$ 的積分導數 $\\frac{\\mathrm{d}}{\\mathrm{d}x}\\int_{x}^{x^2} \\sin t\\,\\mathrm{d}t$。導師質詢：『如何用區間可加性將它拆成以常數為下限的兩個積分？寫出連鎖律的負號是怎麼來的！』'}, {'id': 'D1 11.3', 'desc': '學員丙上黑板論證牛頓-萊布尼茲公式的成立前提。導師詰問：『如果被積函數在區間內部有一個無窮間斷點（如 $f(x) = 1/x^2$ 在 $[-1, 1]$），直接套用牛頓-萊布尼茲公式會算出負數面積，為什麼算出來的結果荒唐至極？』'}], 'unseen_sandbox_scenarios': [{'id': 'U1 11.1', 'desc': '粒子在量子勢阱中，波函數累積機率分佈 $P(x) = \\int_{-\\infty}^x |\\psi(y)|^2\\,\\mathrm{d}y$，現場利用 FTC 證明機率密度等於分佈函數導數，並驗證全空間機率歸一化。'}, {'id': 'U1 11.2', 'desc': '宇宙學紅移隨時間累積，光子在膨脹宇宙中傳播，共動距離與尺度因子變限積分對宇宙時求導，現場構造哈勃定律微積分微分式。'}, {'id': 'U1 11.3', 'desc': '核反應堆中碘-135 衰變累積氙-135，中子通量吸收率隨時間累積，現場建立毒物積累的變限積分微商控制方程。'}], 'system_trivialization_arsenal': [{'id': 'K1 11.1', 'desc': '高中聯考壓軸極限題：求 $\\lim_{x\\to 0} \\frac{\\int_0^x t \\ln(1+t)\\,\\mathrm{d}t}{x^3}$。傳統做法毫無頭緒，利用羅必達法則配合 FTC-1，求導一次直接秒殺得出結果 $\\frac{1}{3}$。'}, {'id': 'K1 11.2', 'desc': '高三模考函數壓軸題：已知 $f(x) = x + \\int_0^1 f(t)\\,\\mathrm{d}t$，求 $f(x)$ 表達式。將定積分視為常數 $C$，兩行解出一元一次方程得 $C=1/2, f(x)=x+1/2$。'}, {'id': 'K1 11.3', 'desc': "競賽分析題：已知 $f(x)$ 連續且 $\\int_0^x f(t)\\,\\mathrm{d}t = [f(x)]^2$，求 $f(x)$。兩端求導直接化為一階微分方程 $f(x) = 2f(x)f'(x)$，秒解出 $f(x) = \\frac{1}{2}x$。"}]}}, {'id': 12, 'title': '冪函數反導積分與第一面積矩（形心代數反演）', 'book_blueprint': '將冪法則求導反轉為不定積分公式 $\\int x^n\\,\\mathrm{d}x = \\frac{x^{n+1}}{n+1}$；引入連續體第一面積矩（First Moment of Area）$Q = \\int x\\,\\mathrm{d}A$；公理推導幾何形心（Centroid）坐標 $\\bar{x} = \\frac{\\int x\\,\\mathrm{d}A}{\\int \\mathrm{d}A}$；將阿基米德槓桿原理昇華為連續微積分泛函。', 'dojo_core': '黑板直擊：在黑板上畫出任意均勻三角形與半圓盤，不用初等幾何拼湊，純憑建立微元坐標帶領全班手算形心坐標（三角形 $\\bar{y} = \\frac{1}{3}h$、半圓盤 $\\bar{y} = \\frac{4R}{3\\pi}$），以微積分反演徹底摧毀中學繁複幾何輔助線迷信。', 'formulas': [{'id': 'Eq 12.1', 'name': '單項式冪函數不定積分公理式', 'latex': '\\int x^n\\,\\mathrm{d}x = \\frac{x^{n+1}}{n+1} + C \\quad (n \\neq -1)'}, {'id': 'Eq 12.2', 'name': '連續平面域質量總面積積分式', 'latex': 'A = \\int_a^b \\big(f(x) - g(x)\\big)\\,\\mathrm{d}x = \\int \\mathrm{d}A'}, {'id': 'Eq 12.3', 'name': '對坐標軸第一面積矩定義式', 'latex': 'Q_y = \\int_a^b x\\,\\mathrm{d}A = \\int_a^b x\\big(f(x) - g(x)\\big)\\,\\mathrm{d}x, \\quad Q_x = \\int_a^b \\frac{f(x)+g(x)}{2}\\,\\mathrm{d}A'}, {'id': 'Eq 12.4', 'name': '形心坐標微積分算子封閉式', 'latex': '\\bar{x} = \\frac{Q_y}{A} = \\frac{\\int_a^b x\\,\\mathrm{d}A}{\\int_a^b \\mathrm{d}A}, \\quad \\bar{y} = \\frac{Q_x}{A} = \\frac{\\int_a^b \\frac{1}{2}[f^2(x) - g^2(x)]\\,\\mathrm{d}x}{\\int_a^b [f(x) - g(x)]\\,\\mathrm{d}x}'}, {'id': 'Eq 12.5', 'name': '均勻直角三角形形心高度定理解', 'latex': 'y(x) = h\\left(1 - \\frac{x}{b}\\right) \\implies \\bar{y} = \\frac{\\int_0^b \\frac{1}{2}y^2(x)\\,\\mathrm{d}x}{\\frac{1}{2}bh} = \\frac{1}{3}h'}, {'id': 'Eq 12.6', 'name': '均勻半圓盤形心高度精確解', 'latex': 'y = \\sqrt{R^2 - x^2} \\implies \\bar{y} = \\frac{\\int_{-R}^R \\frac{1}{2}(R^2 - x^2)\\,\\mathrm{d}x}{\\frac{1}{2}\\pi R^2} = \\frac{\\frac{2}{3}R^3}{\\frac{1}{2}\\pi R^2} = \\frac{4R}{3\\pi}'}, {'id': 'Eq 12.7', 'name': '巴普斯旋轉體第一體積定理式', 'latex': 'V = 2\\pi \\bar{y} A \\quad (\\text{旋轉體體積等於截面積乘以形心轉動路徑})'}], 'problems': {'worked_examples': [{'id': 'Ex 12.1', 'desc': '在黑板上以直角三角形底為 $b$、高為 $h$ 為例，寫出斜邊方程 $y(x) = h(1 - x/b)$，無跳步計算面積 $A$ 與對 $y$ 軸的第一面積矩 $Q_y = \\int_0^b x y(x)\\,\\mathrm{d}x$，求得 $\\bar{x} = \\frac{1}{3}b$。'}, {'id': 'Ex 12.2', 'desc': '推導均勻半圓形薄板 $x^2 + y^2 \\le R^2$（$y \\ge 0$）的質心位置。利用對稱性說明 $\\bar{x} = 0$，利用第一面積矩積分計算 $\\bar{y} = \\frac{4R}{3\\pi}$，並分析為什麼形心高度低於幾何半徑的一半。'}, {'id': 'Ex 12.3', 'desc': "應用巴普斯定理（Pappus's Centroid Theorem），已知圓盤面積為 $\\pi r^2$，其形心到旋轉軸距離為 $R$（$R > r$），一秒求出圓環體（Torus）的體積 $V = (2\\pi R)(\\pi r^2) = 2\\pi^2 R r^2$。"}], 'margin_inquiries': [{'id': 'Q1 12.1', 'desc': '【深水思辨】什麼叫『矩（Moment）』？為什麼位置乘上微元長度叫一階矩（形心），乘上位置平方叫二階矩（轉動慣量），乘上位置立方叫三階矩（偏態）？數學上的矩與物理上的槓桿力矩是如何統一起來的？'}, {'id': 'Q1 12.2', 'desc': '【體制內盲點】中學初等幾何證明三角形重心的交點為 $2:1$，需要做多條輔助線並證明相似三角形。用微積分面積矩來做，只需對線性函數積分一次，為什麼微積分的證明具有壓倒性的普遍適用性？'}, {'id': 'Q1 12.3', 'desc': '【奇偶對稱性化簡】計算半圓形對 $y$ 軸的第一矩 $\\int_{-R}^R x \\sqrt{R^2 - x^2}\\,\\mathrm{d}x$ 時，為什麼不需要找反導數，直接判定被積函數為奇函數，積分對稱區間恆為零？'}], 'foundational_drills': [{'id': 'P1 12.1', 'desc': '閉卷寫出平面圖形形心坐標 $(\\bar{x}, \\bar{y})$ 的雙重積分與單變量積分計算公式。'}, {'id': 'P1 12.2', 'desc': '計算由拋物線 $y = 4 - x^2$ 與 $x$ 軸圍成的平面區域的面積與形心坐標。'}, {'id': 'P1 12.3', 'desc': '求由直線 $y = x$ 與拋物線 $y = x^2$ 圍成的葉狀區域的形心坐標 $(\\bar{x}, \\bar{y})$。'}, {'id': 'P1 12.4', 'desc': '利用巴普斯定理，已知直角三角形繞一條直角邊旋轉得到圓錐體，推導圓錐體積公式 $V = \\frac{1}{3}\\pi r^2 h$。'}], 'interdisciplinary_applications': [{'id': 'P5 12.1', 'desc': '【土木工程梁截面應力】工字鋼梁受彎曲載荷，中性軸（Neutral Axis）必通過截面的形心。利用分塊面積第一矩，計算不對稱 T 型梁截面的中性軸精確高度。'}, {'id': 'P5 12.2', 'desc': '【流體力學浮心分析】船舶漂浮時，浮力作用點為排開液體體積的形心（稱為浮心 $B$）。若船體橫截面為拋物線，計算吃水深度 $d$ 下浮心的垂向坐標。'}, {'id': 'P5 12.3', 'desc': '【大氣壓力中心】平板閘門傾斜浸入水中，水壓力的合力作用點（壓力中心）比形心更深，利用第一面積矩與二階慣性矩證明壓力中心偏移量 $\\Delta y = \\frac{I_{xc}}{y_c A}$。'}, {'id': 'P5 12.4', 'desc': '【質心系運動學】兩體問題中，定義質心坐標 $\\mathbf{R}_{\\text{cm}} = \\frac{m_1\\mathbf{r}_1 + m_2\\mathbf{r}_2}{m_1+m_2}$，證明在無外力條件下質心速度微商 $\\frac{\\mathrm{d}\\mathbf{R}_{\\text{cm}}}{\\mathrm{d}t} = \\text{const}$。'}], 'deepwater_challenges': [{'id': 'P9 12.1', 'desc': '【半球面立體質心】求均勻實心半球體 $x^2 + y^2 + z^2 \\le R^2$（$z \\ge 0$）的質心高度。將半球體分割為薄圓盤薄片微元，積分布局得 $\\bar{z} = \\frac{3}{8}R$。'}, {'id': 'P9 12.2', 'desc': '【阿基米德浮體平衡穩定性】利用形心與穩心（Metacenter）的高度差，推導浮體微小傾斜時回復力矩的微商判據，證明穩心半徑公式 $BM = \\frac{I}{V}$。'}], 'dojo_defense_tasks': [{'id': 'D1 12.1', 'desc': '學員甲在黑板求拋物線與軸圍成面積的形心 $\\bar{y}$，直接套用 $\\frac{\\int y\\,\\mathrm{d}x}{A}$。導師當面攔截：『縱坐標的矩微元不是點！垂直條微元的高度是 $y(x)$，它的形心在自身的半高 $\\frac{1}{2}y(x)$ 處！所以微元矩是 $\\frac{1}{2}y^2\\,\\mathrm{d}x$！公式推導完全錯了，重推！』'}, {'id': 'D1 12.2', 'desc': '學員乙被要求在黑板用巴普斯定理求半球體表面積。導師質詢：『巴普斯第一定理要求旋轉軸與母線在同一平面且不相交，你如何選取母線（四分之一圓弧）的形心？弧長的形心與面積的形心為什麼不同？』'}, {'id': 'D1 12.3', 'desc': '學員丙上黑板論述三角形三條中線交於一點的微積分本質。導師詰問：『如果把三角形換成任意非凸多邊形，重心依然唯一存在嗎？微積分如何保證這一點？』'}], 'unseen_sandbox_scenarios': [{'id': 'U1 12.1', 'desc': '火箭鼻錐外形設計為馮·卡門（von Kármán）氣動旋轉體，現場構造其母線方程的體積與縱向質心坐標積分。'}, {'id': 'U1 12.2', 'desc': '極端條件下中子星外殼密度隨深度呈非線性變化 $\\rho(z) = \\rho_0 (1 + z/H)^3$，現場構造外殼層等效重力質心。'}, {'id': 'U1 12.3', 'desc': '機器人雙足步行中零力矩點（ZMP, Zero Moment Point），現場構造多連桿系統動態質量矩與地表反作用力平衡方程。'}], 'system_trivialization_arsenal': [{'id': 'K1 12.1', 'desc': '高中物理競賽題：半徑為 $R$ 的半球形碗內裝滿水，將水全部舀出需要克服重力做多少功。傳統解法分層微元繁瑣代入，直接視全部水集中於質心 $\\bar{z} = \\frac{3}{8}R$，以功等於重力乘質心位移 $W = mg \\bar{z} = (\\rho \\frac{2}{3}\\pi R^3 g)(\\frac{3}{8}R) = \\frac{1}{4}\\pi \\rho g R^4$ 兩行秒殺。'}, {'id': 'K1 12.2', 'desc': '高二數甲模擬題：曲線 $y = \\sqrt{x}$ 與 $y=x^2$ 旋轉體體積，利用巴普斯定理配合截面形心，心算 10 秒得出旋轉體積。'}, {'id': 'K1 12.3', 'desc': '物理力學難題：均勻懸鏈線或折角金屬絲的平衡掛點問題，直接求各段線元形心做重心加權，一分鐘內鎖定平衡傾角。'}]}}, {'id': 13, 'title': '變力做功線積分與位能曲面梯度力（保守力場本質）', 'book_blueprint': '將體制內死記硬背的『功等於力乘以位移 $W=Fs$』徹底拋棄；建立變力沿任意路徑做功的線積分定義 $W = \\int_C \\mathbf{F} \\cdot \\mathrm{d}\\mathbf{r}$；引入勢能函數 $U(\\mathbf{r})$ 與保守場的旋度為零條件；用負梯度算子 $\\mathbf{F} = -\\nabla U$ 統一彈簧彈力、萬有引力與靜電力。', 'dojo_core': '黑板直擊：在黑板上以引力場 $\\mathbf{F} = -\\frac{GMm}{r^2}\\hat{\\mathbf{r}}$ 為核心，取兩條完全不同的曲折路徑計算功，實彈演示路徑獨立性；導師當場刺穿『重力勢能 $mgh$ 到底以哪裡為零勢能面』的偽哲學爭論。', 'formulas': [{'id': 'Eq 13.1', 'name': '變力做功線積分公理定義式', 'latex': 'W = \\int_{P_1}^{P_2} \\mathbf{F} \\cdot \\mathrm{d}\\mathbf{r} = \\int_{t_1}^{t_2} \\left( F_x \\frac{\\mathrm{d}x}{\\mathrm{d}t} + F_y \\frac{\\mathrm{d}y}{\\mathrm{d}t} + F_z \\frac{\\mathrm{d}z}{\\mathrm{d}t} \\right) \\mathrm{d}t'}, {'id': 'Eq 13.2', 'name': '彈簧虎克定律變力做功二次式', 'latex': 'W = \\int_0^x (-ks)\\,(-\\mathrm{d}s) = \\int_0^x ks\\,\\mathrm{d}s = \\frac{1}{2}kx^2 \\quad (\\text{三角形面積微元})'}, {'id': 'Eq 13.3', 'name': '萬有引力做功與引力勢能差式', 'latex': 'W = \\int_{r_1}^{r_2} \\left(-\\frac{GMm}{r^2}\\right)\\mathrm{d}r = \\left[ \\frac{GMm}{r} \\right]_{r_1}^{r_2} = -\\big(U(r_2) - U(r_1)\\big)'}, {'id': 'Eq 13.4', 'name': '保守力場路徑獨立性等價公理', 'latex': '\\oint_C \\mathbf{F} \\cdot \\mathrm{d}\\mathbf{r} = 0 \\iff \\mathbf{F} = -\\nabla U = -\\left(\\frac{\\partial U}{\\partial x}\\hat{\\mathbf{i}} + \\frac{\\partial U}{\\partial y}\\hat{\\mathbf{j}} + \\frac{\\partial U}{\\partial z}\\hat{\\mathbf{k}}\\right)'}, {'id': 'Eq 13.5', 'name': '一維保守力負微商恢復力定理', 'latex': 'F(x) = -\\frac{\\mathrm{d}U}{\\mathrm{d}x} \\quad (\\text{力永遠指向勢能下降最陡方向})'}, {'id': 'Eq 13.6', 'name': '平衡位置勢能二階微商穩定性判據', 'latex': "U'(x_0) = 0 \\implies \\begin{cases} U''(x_0) > 0 & \\text{穩定平衡（微振盪）} \\\\ U''(x_0) < 0 & \\text{不穩定平衡（分崩離析）} \\end{cases}"}, {'id': 'Eq 13.7', 'name': '非保守耗散力路徑依賴循環損耗式', 'latex': '\\oint_C \\mathbf{f}_{\\text{friction}} \\cdot \\mathrm{d}\\mathbf{r} = -\\mu N \\oint_C \\mathrm{d}s = -\\mu N \\cdot \\text{Perimeter} < 0'}], 'problems': {'worked_examples': [{'id': 'Ex 13.1', 'desc': '一質點在平面力場 $\\mathbf{F} = (2xy)\\hat{\\mathbf{i}} + (x^2)\\hat{\\mathbf{j}}$ 作用下，由原點 $(0, 0)$ 移動到點 $(1, 1)$。分別沿直線路徑 $y=x$ 與拋物線路徑 $y=x^2$ 計算線積分做功，證明兩者嚴格相等，並找出勢能函數 $U(x, y) = -x^2 y + C$。'}, {'id': 'Ex 13.2', 'desc': '在黑板上推導萬有引力勢能：以無窮遠處為參考點 $U(\\infty) = 0$，計算將質量為 $m$ 的物體從半徑 $R$ 移動到無窮遠引力所做的功，嚴格導出 $U(r) = -\\frac{GMm}{r}$，並解剖負號的物理束縛態意義。'}, {'id': 'Ex 13.3', 'desc': "給定雙原子分子間作用勢能為 Lennard-Jones 形式 $U(r) = 4\\epsilon \\left[ \\left(\\frac{\\sigma}{r}\\right)^{12} - \\left(\\frac{\\sigma}{r}\\right)^6 \\right]$。求分子間平衡距離 $r_0$，並求二階導數 $U''(r_0)$，推導分子在平衡位置附近微小振盪的等效彈簧剛度 $k_{\\text{eff}}$。"}], 'margin_inquiries': [{'id': 'Q1 13.1', 'desc': '【深水思辨】為什麼勢能定義式前面必須有一個『負號』 $\\mathbf{F} = -\\nabla U$？如果定義為正梯度會發生什麼？（物體受力方向永遠朝向勢能更低、能量更穩定的方向，負號是宇宙自發穩定的公理體現）。'}, {'id': 'Q1 13.2', 'desc': '【體制內盲點】中學課本說『重力勢能等於 $mgh$』，引力勢能又等於 $-GMm/r$。這兩個公式一個帶負號、一個是正的，一個與 $h$ 成正比、一個與 $r$ 成反比，高中生經常精神分裂。如何用泰勒展開一秒證明前者就是後者在地表附近的線性近似？'}, {'id': 'Q1 13.3', 'desc': '【摩擦力為什麼沒有勢能？】摩擦力的功為什麼無法寫成任何狀態函數的差？閉合路徑積分 $\\oint \\mathbf{f} \\cdot \\mathrm{d}\\mathbf{r} \\neq 0$ 是如何揭示耗散系統與時間不可逆性的？'}], 'foundational_drills': [{'id': 'P1 13.1', 'desc': '閉卷默寫力做功的線積分矢量形式，以及一維保守力與勢能微商的關係式。'}, {'id': 'P1 13.2', 'desc': '質點受一維變力 $F(x) = 3x^2 - 4x + 1$ 作用，求物體從 $x=1$ 移動到 $x=3$ 該力所做的總功。'}, {'id': 'P1 13.3', 'desc': '已知勢能函數為 $U(x) = x^3 - 3x^2 - 9x + 5$，求平衡位置，並利用二階微商判定各平衡點的穩定性。'}, {'id': 'P1 13.4', 'desc': '證明力場 $\\mathbf{F} = y\\hat{\\mathbf{i}} - x\\hat{\\mathbf{j}}$ 是非保守力場，計算沿單位圓逆時針旋轉一周該力所做的功。'}], 'interdisciplinary_applications': [{'id': 'P5 13.1', 'desc': '【靜電場電勢能】點電荷電場 $\\mathbf{E} = \\frac{q}{4\\pi\\epsilon_0 r^2}\\hat{\\mathbf{r}}$，將試探電荷 $q_0$ 從點 $A$ 沿任意曲線移到點 $B$，證明電場力做功只與始末位置的電勢差有關 $W = q_0(V_A - V_B)$。'}, {'id': 'P5 13.2', 'desc': '【化學反應過渡態理論】化學反應坐標上的勢能面（PES），反應物跨越活化能勢壘（Saddle Point 鞍點），利用一階導數為零、主反應方向二階導數為負，構造過渡態分子幾何。'}, {'id': 'P5 13.3', 'desc': '【流體伯努利方程第一性原理】沿流線的微元流體受壓力梯度力 $-\\nabla P$ 與重力做功，利用動能定理定積分一步導出伯努利恆等式 $P + \\frac{1}{2}\\rho v^2 + \\rho g z = \\text{const}$。'}, {'id': 'P5 13.4', 'desc': '【非線性吸振器】磁懸浮減震系統勢能為 $U(x) = \\frac{1}{2}kx^2 + \\frac{1}{4}\\beta x^4$（杜芬振子 Duffing Oscillator），利用微商求恢復力，分析強非線性硬彈簧特性。'}], 'deepwater_challenges': [{'id': 'P9 13.1', 'desc': '【格林定理與保守力旋度】利用二維格林定理 $\\oint_C (P\\,\\mathrm{d}x + Q\\,\\mathrm{d}y) = \\iint_D \\left(\\frac{\\partial Q}{\\partial x} - \\frac{\\partial P}{\\partial y}\\right)\\mathrm{d}x\\mathrm{d}y$，嚴格證明力場無旋 $\\nabla \\times \\mathbf{F} = \\mathbf{0}$ 是保守場路徑無關的充要條件。'}, {'id': 'P9 13.2', 'desc': '【龐加萊引理與單連通區域】構造具有奇異點的力場 $\\mathbf{F} = \\frac{-y\\hat{\\mathbf{i}} + x\\hat{\\mathbf{j}}}{x^2 + y^2}$，證明其局部旋度處處為零，但環繞原點一周線積分卻等於 $2\\pi$，深入剖析拓撲非單連通結構對保守場的破壞。'}], 'dojo_defense_tasks': [{'id': 'D1 13.1', 'desc': '學員甲在黑板求彈簧做功，寫出 $W = F \\cdot x = (-kx) \\cdot x = -kx^2$。導師雷霆震怒：『彈簧拉伸過程中力是恆定的嗎？把變力當成恆力乘位移，微積分白學了！立刻在黑板畫出 $F-x$ 三角形面積，用定積分重算！』'}, {'id': 'D1 13.2', 'desc': '學員乙被要求在黑板推導由 $U(r) = -GMm/r$ 到地表 $mgh$ 的極限過渡。導師質詢：『令 $r = R+h$ 展開，分母提取 $R$ 後用泰勒一階展開，把丟掉的高階無窮小項的物理量綱精確寫出來！』'}, {'id': 'D1 13.3', 'desc': '學員丙上黑板分析質點在勢阱中的微振盪。導師詰問：『為什麼任何平滑勢能曲面在極小值附近的微振盪都可以近似為簡諧運動？用泰勒公式二階展開向全體學員論證簡諧運動在宇宙中的普遍性！』'}], 'unseen_sandbox_scenarios': [{'id': 'U1 13.1', 'desc': '航天器在拉格朗日點 $L_1$ 附近的有效勢能面（包含萬有引力勢能與離心勢能），現場構造有效勢能梯度並求鞍點平衡的不穩定發散特徵時間。'}, {'id': 'U1 13.2', 'desc': '高分子聚合物鏈拉伸過程中構象熵勢能 $U(x) = -T S(x)$，現場構造熵力（Entropic Force）$F = -\\frac{\\mathrm{d}U}{\\mathrm{d}x}$ 的反常胡克定律。'}, {'id': 'U1 13.3', 'desc': '超導約瑟夫森結的宏觀量子相位差勢能 $U(\\phi) = -E_J \\cos\\phi - \\frac{\\hbar I}{2e}\\phi$（傾斜搓衣板勢），現場構造超導電流跳變的臨界條件。'}], 'system_trivialization_arsenal': [{'id': 'K1 13.1', 'desc': '高中物理指考壓軸題：一根長度為 $L$、質量為 $M$ 的均勻柔軟繩索懸於光滑桌邊，下垂長度為 $a$，由靜止釋放求滑落瞬間末速度。傳統分段動能繁瑣，將繩索視為連續體求勢能變化量 $\\Delta U = -\\frac{M}{2L}(L^2 - a^2)g$，動能定理 2 行直接秒出末速度。'}, {'id': 'K1 13.2', 'desc': '高二物理難題：物體在立方反比引力場 $F = -k/r^3$ 中運動，求勢能函數與脫離速度。用定積分 $\\int r^{-3}\\,\\mathrm{d}r$ 10 秒得出 $U(r) = -\\frac{k}{2r^2}$。'}, {'id': 'K1 13.3', 'desc': '競賽極值題：兩帶電粒子固定，求第三個粒子在連線垂直平分線上的受力極大值點。直接構造電勢函數並求二階導數為零，比傳統三角代換求導快三倍。'}]}}, {'id': 14, 'title': '對數微積分發明與自指自然常數 e（填補反導黑洞與連續複利基石）', 'book_blueprint': '高中數學強行定義 e = 2.71828...，卻從未向學生解釋為何要發明這個古怪的常數。本章從反導函數的唯一黑洞切入：冪函數積分 int x^n dx = x^{n+1}/(n+1) 在 n = -1 時分母為零崩潰！為填補曲線 1/x 下方幾何面積的空白，人類發明了自然對數定義式 ln(x) = int_1^x (1/t) dt；利用換元法嚴格證明對數性質 ln(ab) = ln(a) + ln(b)；再由反函數定理定義指數函數 y = e^x，其微商 d/dx(e^x) = e^x，具備『變化率恆等於自身』的自指神性！最後以連續複利模型 lim_{n -> inf} (1 + 1/n)^n = e 連接放射性衰變與人口指數增長，完成超越函數微積分基石。 本章在前置位置徹底確立對數與指數微積分，為後續物理場域的火箭推進、RC 暫態電路、放射性衰變與熱力學等溫做功提供零賒帳、零跳步的堅實數學底座。', 'dojo_core': '黑板四分區實彈攻防：一區在黑板畫出雙曲線 y = 1/x，塗滿 [1, x] 區間的面積微元 dt/t；二區利用面積的可加性證明 ln(ab) = ln(a) + ln(b)，展示微積分如何生長出代數法則；三區推導指數函數的自指导數，說明相空間中斜率恆等於縱坐標的幾何含義；四區以複利增長與半衰期實例擊碎死記硬背。', 'formulas': [{'id': 'Eq 14.1', 'name': '自然對數幾何微積分定義式', 'latex': '\\ln x = \\int_1^x \\frac{1}{t}\\,\\mathrm{d}t \\quad (x > 0)'}, {'id': 'Eq 14.2', 'name': '自然對數核心微商算子式', 'latex': '\\frac{\\mathrm{d}}{\\mathrm{d}x} \\ln x = \\frac{1}{x}'}, {'id': 'Eq 14.3', 'name': '自然常數極限定義式', 'latex': 'e = \\lim_{n \\to \\infty} \\left(1 + \\frac{1}{n}\\right)^n = \\lim_{h \\to 0} (1 + h)^{1/h}'}, {'id': 'Eq 14.4', 'name': '自指指數函數微商式', 'latex': '\\frac{\\mathrm{d}}{\\mathrm{d}x} e^x = e^x'}, {'id': 'Eq 14.5', 'name': '任意底數指數函數求導式', 'latex': '\\frac{\\mathrm{d}}{\\mathrm{d}x} a^x = a^x \\ln a \\quad (a > 0)'}, {'id': 'Eq 14.6', 'name': '對數求導法通用算子式', 'latex': "\\frac{\\mathrm{d}}{\\mathrm{d}x} \\ln |y(x)| = \\frac{y'(x)}{y(x)}"}, {'id': 'Eq 14.7', 'name': '指數生長與衰變模型解析式', 'latex': '\\frac{\\mathrm{d}y}{\\mathrm{d}t} = k y \\implies y(t) = y_0 e^{kt}'}], 'problems': {'worked_examples': [{'id': 'Ex 14.1', 'desc': '純粹利用定義 ln(x) = int_1^x (1/t) dt 與換元積分法，不依賴任何指數假設，無跳步證明 ln(a*b) = ln(a) + ln(b)。'}, {'id': 'Ex 14.2', 'desc': '利用對數求導法求 y = x^x (x > 0) 的導函數，並求其局部極小值點與極小值。'}, {'id': 'Ex 14.3', 'desc': '放射性同位素半衰期為 T_half，列出衰變微分方程并求出衰變常數 lambda = ln(2) / T_half，計算經 3 個半衰期後剩餘質量比例。'}], 'margin_inquiries': [{'id': 'Q1 14.1', 'desc': '為什麼在所有指數函數 a^x 中，只有以 e 為底時，在 x=0 處的切線斜率恰好等於 1？'}, {'id': 'Q1 14.2', 'desc': '如果冪法則 int x^n dx 在 n = -1 時直接套公式會出現 1/0，微積分是如何通過面積積分拯救這個奇異點的？'}, {'id': 'Q1 14.3', 'desc': '對數求導法在處理連乘多項式 y = (x-1)(x-2)...(x-n) 時，為何比直接使用乘積法則快得多？'}], 'foundational_drills': [{'id': 'P1 14.1', 'desc': '求 f(x) = ln(x + sqrt{x^2 + 1}) 的一階導函數，化簡為最簡式。'}, {'id': 'P1 14.2', 'desc': '求定積分 int_1^e (ln x / x) dx。'}, {'id': 'P1 14.3', 'desc': '利用隱函數與對數求導求方程 e^y + x y = e 在點 (0, 1) 的切線斜率。'}, {'id': 'P1 14.4', 'desc': '計算極限 lim_{x -> 0} (e^x - 1 - x) / x^2。'}], 'interdisciplinary_applications': [{'id': 'P5 14.1', 'desc': '【化學一級反應動力學】反應物濃度滿足 d[A]/dt = -k[A]，積分證明濃度半衰期與初始濃度完全無關。'}, {'id': 'P5 14.2', 'desc': '【聲音分貝與對數尺度】聲壓級分貝定義 beta = 10 log_{10}(I / I_0)，利用微分 d(beta) 分析聲強增加 10 倍時分貝的微元增量。'}, {'id': 'P5 14.3', 'desc': '【大氣等溫氣壓公式】結合流體力學 dP = -rho g dz 與理想氣體狀態方程，分離變數法推導氣壓隨高度衰減公式 P(z) = P_0 e^{-M g z / RT}。'}, {'id': 'P5 14.4', 'desc': '【計算機二元檢索樹複雜度】證明平衡二元樹高度隨節點數 N 滿足 h = O(ln N)，並用微積分估算調和級數 sum_{k=1}^N (1/k) approx ln N。'}], 'deepwater_challenges': [{'id': 'P9 14.1', 'desc': '嚴格證明歐拉-馬歇羅尼常數 gamma = lim_{n -> inf} (sum_{k=1}^n 1/k - ln n) 的極限存在性，並以幾何曲邊梯形剩餘三角形夾擠之。'}, {'id': 'P9 14.2', 'desc': '非線性生長邏輯斯諦方程式（Logistic Equation）dy/dt = r y (1 - y/K)，利用部分分式分離變數法求出 S 型曲線解析解 y(t)。'}], 'dojo_defense_tasks': [{'id': 'D1 14.1', 'desc': '學員求 d/dx(2^x) 寫成 x * 2^{x-1}，導師截停：『這是指數函數，不是冪函數！在黑板寫出化為自然底 e 的標準換底推導！』'}, {'id': 'D1 14.2', 'desc': '學員試圖計算 int (1/x) dx 寫出 ln(x)，導師指出：『x 為負數時怎麼辦？立刻補上絕對值符號並分區間證明！』'}, {'id': 'D1 14.3', 'desc': '學員在黑板推導 lim (1 + 1/n)^n，無法說明為何極限必然介於 2 與 3 之間，要求用二項式定理單調有界定理當場證畢。'}], 'unseen_sandbox_scenarios': [{'id': 'U1 14.1', 'desc': '未知破局：設函數 f(x) 滿足 f(xy) = f(x) + f(y) 且在 x=1 可導，求證 f(x) 必然為對數函數 C ln x。'}, {'id': 'U1 14.2', 'desc': '未知破局：一容器內氣體滲漏率正比於容器內外壓差 d(Delta P)/dt = -k Delta P，求解壓差衰減曲線。'}, {'id': 'U1 14.3', 'desc': '未知破局：求方程 e^x = 3x 在實數範圍內的實根個數與近似解。'}], 'system_trivialization_arsenal': [{'id': 'K1 14.1', 'desc': '體制內考題秒殺：高中大考指數比較大小題（如 e^pi 與 pi^e），微積分選手考慮 f(x) = ln(x)/x 的單調性，10 秒秒殺。'}, {'id': 'K1 14.2', 'desc': '體制內考題秒殺：放射性剩餘質量計算題，微積分學員直接套用 m = m_0 2^{-t/T} 3 秒心算出答案。'}, {'id': 'K1 14.3', 'desc': '體制內考題秒殺：複雜分式乘積求導，微積分選手取對數求導 1 行列出答案，碾壓死算商法則的學生。'}]}}]}
